      SUBROUTINE DFRINJCC     CALCULATES PARTIAL DERIVATIVES OF BENDING MAGNET FRINGE FIELDC     MATRIX ELEMENTS WITH RESPECT TO POLE FACT ROTATION ANGLECC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM2A.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'R.CIN'CC     LOCAL VARIABLESC      REAL  BEVCC--------------------------------------------------------------------      LINEAR = .FALSE.      BEV = DPARM*UNITI(7)      IF (TYPE .EQ. 28 .AND. JV .EQ. 2) BEV = 0.5*BEV      RV(2,1) = BEV*H0*SB**2      RV(4,3) = - BEV*H0*SB**2     1        + 2.0*BEV*H0**2*APB(2)*LAYL*SB*TB*(5.0*SB**2 + TB**2)C      RETURN      END